#!/usr/bin/env python3
import paramiko
import sys
import os

# Configuration
TARGET_HOST = '127.0.0.1'
TARGET_PORT = 22
USERNAME = 'testuser'  # Replace with a valid user or use root if permitted
PASSWORD = 'testpass'  # Replace with valid password or use key auth

def simulate_vulnerable_client():
    """
    Simulates an SSH client that bypasses host key verification.
    This demonstrates the vulnerability described in RFC 4251 Section 4.1 and 9.3.4,
    where a client accepts an unverified host key, enabling MitM attacks.
    """
    print(f"[*] Connecting to {TARGET_HOST}:{TARGET_PORT} with host key verification BYPASSED...")
    
    # Create an SSH client
    client = paramiko.SSHClient()
    
    # VULNERABILITY: Explicitly set policy to auto-add unverified host keys
    # This mimics the behavior described in the RFC where the client skips validation
    client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    
    try:
        # Attempt connection
        client.connect(
            hostname=TARGET_HOST,
            port=TARGET_PORT,
            username=USERNAME,
            password=PASSWORD,
            timeout=5
        )
        
        print("[+] Connection successful! Host key was accepted without prior verification.")
        print("[!] In a MitM scenario, an attacker could now inject their own host key.")
        
        # Execute a harmless command to prove session establishment
        stdin, stdout, stderr = client.exec_command('echo "Session established with unverified host key"')
        output = stdout.read().decode().strip()
        print(f"[+] Command output: {output}")
        
    except paramiko.AuthenticationException:
        print("[-] Authentication failed. Check username/password.")
    except paramiko.SSHException as e:
        print(f"[-] SSH error: {e}")
    except Exception as e:
        print(f"[-] Connection failed: {e}")
    finally:
        client.close()
        print("[*] Connection closed.")

def simulate_secure_client():
    """
    Simulates a secure SSH client that enforces strict host key verification.
    This demonstrates the patched behavior where unverified keys are rejected.
    """
    print(f"\n[*] Connecting to {TARGET_HOST}:{TARGET_PORT} with STRICT host key verification...")
    
    client = paramiko.SSHClient()
    
    # SECURE: Load system host keys and reject unknown hosts
    client.load_system_host_keys()
    client.set_missing_host_key_policy(paramiko.RejectPolicy())
    
    try:
        client.connect(
            hostname=TARGET_HOST,
            port=TARGET_PORT,
            username=USERNAME,
            password=PASSWORD,
            timeout=5
        )
        print("[+] Connection successful with verified host key.")
    except paramiko.SSHException as e:
        if 'reject' in str(e).lower() or 'unknown' in str(e).lower():
            print("[+] Connection rejected as expected: Host key not verified.")
        else:
            print(f"[-] SSH error: {e}")
    except Exception as e:
        print(f"[-] Connection failed: {e}")
    finally:
        client.close()

if __name__ == '__main__':
    print("=== SSH Host Key Verification Bypass PoC ===")
    print("This script demonstrates the vulnerability where clients accept unverified host keys.")
    print("RFC 4251 Section 4.1: 'The protocol provides the option that the server name - host key association is not checked...'")
    print("RFC 4251 Section 9.3.4: 'Such usage is vulnerable to man-in-the-middle attacks.'")
    print("="*60)
    
    # Run vulnerable simulation
    simulate_vulnerable_client()
    
    # Run secure simulation for comparison
    simulate_secure_client()